import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Fills the precache list into `build/client/sw.js` after `react-router build`.
 *
 * Hand-written rather than generated by a plugin, as in Rasika Classes: the worker is short and
 * the one thing worth seeing at a glance is what it caches.
 */

// Files the worker must not cache: itself (the browser fetches it fresh to look for updates),
// the SPA fallback (served by the CDN, never requested by name), and the crawler file.
const SKIP = new Set(['/sw.js', '/__spa-fallback.html', '/robots.txt']);

/**
 * Pairs each built file with the URL the app requests it by. A prerendered page is requested by
 * its path, not its file name: `/about`, not `/about/index.html`, and the worker's offline
 * fallback matches on the path.
 */
export function precacheEntries(files) {
  return files
    .map(file => ({ file, url: `/${file.split(sep).join('/')}` }))
    .filter(({ url }) => !SKIP.has(url) && !url.endsWith('.DS_Store'))
    .map(({ file, url }) => {
      if (url === '/index.html') {
        return { file, url: '/' };
      }
      return { file, url: url.endsWith('/index.html') ? url.slice(0, -'/index.html'.length) : url };
    })
    .sort((a, b) => a.url.localeCompare(b.url));
}

/**
 * A hash of every cached URL and its contents. Pages are hashed too: their names do not change
 * when their contents do, so a list of names alone would miss a copy change.
 */
export function precacheVersion(entries, read) {
  const hash = createHash('sha256');
  for (const { file, url } of entries) {
    hash.update(url);
    hash.update(read(file));
  }
  return hash.digest('hex').slice(0, 12);
}

function listFiles(dir) {
  return readdirSync(dir, { withFileTypes: true, recursive: true })
    .filter(entry => entry.isFile())
    .map(entry => relative(dir, join(entry.parentPath ?? entry.path, entry.name)));
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const outDir = fileURLToPath(new URL('../build/client/', import.meta.url));
  const entries = precacheEntries(listFiles(outDir));
  const version = precacheVersion(entries, file => readFileSync(join(outDir, file)));
  const urls = entries.map(({ url }) => url);
  const swPath = join(outDir, 'sw.js');
  const sw = readFileSync(swPath, 'utf8')
    .replace("'__VERSION__'", JSON.stringify(version))
    .replace('__PRECACHE__;', `${JSON.stringify(urls, null, 2)};`);
  // A placeholder left behind is a worker that fails to evaluate, which a browser reports only
  // as "registration failed". Stop the build instead.
  if (sw.includes('__VERSION__') || sw.includes('__PRECACHE__')) {
    throw new Error('sw.js: a placeholder was not filled in');
  }
  writeFileSync(swPath, sw);
  console.log(`sw.js: ${urls.length} files precached, version ${version}`);
}
